 private void paste(BufferedImage stamp,int x,int y){int w=stamp.getWidth(),h=stamp.getHeight();int[] data=new int[2+w*h];data[0]=w;data[1]=h;stamp.getRGB(0,0,w,h,data,2,w);if(selection!=null){int dw=DrawingView.nativeWidth(),dh=DrawingView.nativeHeight();for(int sy=0;sy<h;sy++)for(int sx=0;sx<w;sx++){int dx=x+sx,dy=y+sy;if(dx<0||dy<0||dx>=dw||dy>=dh||selection[dy*dw+dx]==0)data[2+sy*w+sx]=0;}}DrawingView.nativePasteSelection(data,x,y);refresh();}
