 private record CurveState(ArrayList<Point2D.Double> nodes,ArrayList<ArrayList<Point2D.Double>> others,java.util.Map<Point2D.Double,Float> tensions,int color,int width,float opacity,byte[] selection){}
 private final java.util.ArrayDeque<CurveState> draftUndo=new java.util.ArrayDeque<>(),draftRedo=new java.util.ArrayDeque<>();
 private void stashDraft(){draftUndo.push(snapshotCurve());draftRedo.clear();}
 private final java.util.Map<Long,CurveState> savedCurves=new java.util.HashMap<>(),redoCurves=new java.util.HashMap<>();
 private CurveState snapshotCurve(){ArrayList<ArrayList<Point2D.Double>> lines=new ArrayList<>();for(var line:otherCurves)lines.add(new ArrayList<>(line));return new CurveState(new ArrayList<>(curve),lines,new java.util.IdentityHashMap<>(tensions),color,size,opacity,selection==null?null:selection.clone());}
 private void restoreCurve(CurveState state){curve.clear();curve.addAll(state.nodes());otherCurves.clear();for(var line:state.others())otherCurves.add(new ArrayList<>(line));tensions.clear();tensions.putAll(state.tensions());color=state.color();size=state.width();opacity=state.opacity();selection=state.selection()==null?null:state.selection().clone();if(selection!=null)maskBounds();else clearSelection();tool=Tool.LINE;}
 public void commitCurve(){if(curve.size()<2)return;long before=DrawingView.nativeRevision();CurveState state=snapshotCurve();DrawingView.nativeBeginEdit();DrawingView.nativeSetBrushSelection(selection);DrawingView.nativeBeginOpacityStroke(true);PathIterator path=curvePath().getPathIterator(null,.25);double[] xy=new double[6];double x=0,y=0;while(!path.isDone()){int type=path.currentSegment(xy);if(type==PathIterator.SEG_LINETO)DrawingView.nativeAntialiasedStroke((float)x,(float)y,(float)xy[0],(float)xy[1],size/2f,color,opacity,1,false);x=xy[0];y=xy[1];path.next();}DrawingView.nativeEndOpacityStroke();long after=DrawingView.nativeRevision();if(after!=before){savedCurves.put(before,state);redoCurves.put(after,state);}curve.clear();otherCurves.clear();draftUndo.clear();draftRedo.clear();refresh();}
