 public void redo(){if(!draftRedo.isEmpty()){draftUndo.push(snapshotCurve());restoreCurve(draftRedo.pop());refresh();return;}if((DrawingView.nativeHistoryAvailability()&2)==0)return;perform("Rehaciendo…",DrawingView::nativeRedo,()->{curve.clear();otherCurves.clear();draftUndo.clear();draftRedo.clear();clearSelection();refresh();});}
 public boolean removeCurvePoint(){if(curve.isEmpty())return false;if(curveNode>0&&curveNode<curve.size()-1){stashDraft();tensions.remove(curve.remove(curveNode));curveNode=-1;repaint();}return true;}
